entries[47484] = { ["name"] = "Zusammenkauern", ["text"] = "10 Energie\nSofort 45 sek. Abklingzeit\nKauert sich verteidigend zusammen und verringert so 10 Sek. lang jeglichen erlittenen Schaden um 50%, der Ghul kann währenddessen jedoch keine anderen Aktionen ausführen." }
