entries[48266] = { ["name"] = "Frostpräsenz", ["text"] = "Sofort\nStärkt Euch mit der Präsenz des Frostes, erhöht Euren Schaden um 10% und die Runenmachterzeugung um 10%. Es kann jeweils nur eine Präsenz aktiv sein und das Wechseln der Präsenz verbraucht alle aufgebaute Runenmacht." }
